 {key:'pdf1500_1009',label:'Osteossarcoma',kind:'osteosarcoma',entity:'Osteossarcoma pediátrico',assessment:'VALIDATED_AI: tumor ósseo maligno específico, mais comum em ossos longos de adolescentes; tratamento depende de local, extensão, resposta e equipe oncológica especializada.'}
